    fn test_domain_payload_with_status(
        read_time_us: u64,
        row_count: u32,
        changed_rows: u32,
        unit_count: u32,
        changed_unit_count: u32,
        status_flags: u32,
    ) -> Vec<u8> {
        let mut payload = Vec::new();
        payload.extend_from_slice(&0u64.to_le_bytes());
        payload.extend_from_slice(&read_time_us.to_le_bytes());
        payload.extend_from_slice(&row_count.to_le_bytes());
        payload.extend_from_slice(&changed_rows.to_le_bytes());
        payload.extend_from_slice(&unit_count.to_le_bytes());
        payload.extend_from_slice(&changed_unit_count.to_le_bytes());
        payload.extend_from_slice(&status_flags.to_le_bytes());
        payload.extend_from_slice(&0u32.to_le_bytes());
        payload
    }

    fn fold_single_compact_snapshot(raw: &[u8]) -> Value {
        let snapshots = fold_compact_snapshots(raw);
        assert_eq!(
            snapshots.len(),
            1,
            "one folded snapshot for the single compact test hour"
        );
        snapshots.into_iter().next().unwrap()
    }

    fn fold_compact_snapshots(raw: &[u8]) -> Vec<Value> {
        let mut fold = WorldFold::new(replay_game_id("expected-partial/e2e"));
        fold.ingest_stream(raw);
        fold.finish()
            .into_iter()
            .map(|(_, _, bytes)| serde_json::from_slice(&bytes).unwrap())
            .collect()
    }

